```turtle
@prefix ea:   <http://example.org/onto/assessment#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

@base <http://example.org/onto/assessment#> .

<http://example.org/onto/assessment> a owl:Ontology ;
  rdfs:comment "Ontology of educational assessment classifications, built strictly from the supplied corpus. Where the corpus presents conflicting classification schemes for the same concept, both are encoded and the conflict is documented in rdfs:comment." .

#################################################################
# TOP-LEVEL CLASSES
#################################################################

ea:EducationalAssessment a owl:Class ;
  rdfs:label "Educational Assessment" ;
  skos:altLabel "educational evaluation", "assessment" ;
  rdfs:comment "The systematic process of documenting and using empirical data on knowledge, skill, attitudes, aptitude and beliefs to refine programs and improve student learning. Often used interchangeably with 'test' but is broader than testing." .

ea:Test a owl:Class ;
  rdfs:subClassOf ea:EducationalAssessment ;
  rdfs:label "Test" ;
  rdfs:comment "An educational assessment intended to measure a test-taker's knowledge, skill, aptitude, physical fitness, or classification, administered verbally, on paper, on computer, or in a practical setting." .

ea:Examination a owl:Class ;
  owl:equivalentClass ea:Test ;
  rdfs:label "Examination" ;
  skos:altLabel "exam", "evaluation" ;
  rdfs:comment "Corpus states 'An examination (exam or evaluation), or test, is an educational assessment...' treating Examination as synonymous with Test. Note: 'evaluation' is also used elsewhere as a synonym of the broader EducationalAssessment, creating terminological tension between 'evaluation' as a synonym of Test vs of Assessment generally." .

#################################################################
# GRANULARITY
#################################################################

ea:GranularityLevel a owl:Class ;
  owl:disjointUnionOf ( ea:IndividualLearnerGranularity ea:LearningCommunityGranularity
                         ea:CourseGranularity ea:AcademicProgramGranularity
                         ea:InstitutionGranularity ea:EducationalSystemGranularity ) .

ea:IndividualLearnerGranularity a owl:Class .
ea:LearningCommunityGranularity a owl:Class ;
  rdfs:comment "Class, workshop, or other organized group of learners." .
ea:CourseGranularity a owl:Class .
ea:AcademicProgramGranularity a owl:Class .
ea:InstitutionGranularity a owl:Class .
ea:EducationalSystemGranularity a owl:Class .

ea:hasGranularity a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:GranularityLevel .

#################################################################
# AXIS 1: PURPOSE (Placement / Formative / Summative / Diagnostic)
#################################################################

ea:PurposeCategory a owl:Class ;
  owl:disjointUnionOf ( ea:PlacementPurpose ea:FormativePurpose ea:SummativePurpose ea:DiagnosticPurpose ) .

ea:PlacementPurpose a owl:Class .
ea:FormativePurpose a owl:Class .
ea:SummativePurpose a owl:Class .
ea:DiagnosticPurpose a owl:Class .

ea:hasPurpose a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:PurposeCategory .

ea:PlacementAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:PlacementPurpose ] ) ] ;
  skos:altLabel "pre-assessment", "initial assessment", "threshold knowledge test", "TKT" ;
  rdfs:comment "Used to place students according to prior achievement, level of knowledge, or personal characteristics before instruction." .

ea:FormativeAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:FormativePurpose ] ) ] ;
  skos:altLabel "formative evaluation", "formative feedback", "assessment for learning", "educative assessment", "classroom assessment" ;
  rdfs:comment "Carried out throughout a course to modify teaching/learning activities; 'assessment for learning'." .

ea:SummativeAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:SummativePurpose ] ) ] ;
  skos:altLabel "summative evaluation", "assessment of learning" ;
  rdfs:comment "Carried out at the end of a course/project to evaluate learning against a standard." .

ea:DiagnosticAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:DiagnosticPurpose ] ) ] ;
  rdfs:subClassOf ea:FormativeAssessment ;
  skos:altLabel "diagnostic testing" ;
  rdfs:comment "TENSION: one passage lists Placement, Formative, Summative and Diagnostic as four coordinate categories ('Assessment can be divided... Placement, formative, summative and diagnostic assessment'), while another states 'A common form of formative assessment is diagnostic assessment' and 'formative assessment... including diagnostic testing', subordinating Diagnostic under Formative. Both the coordinate listing and the subsumption relation are encoded here." .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:PlacementAssessment ea:FormativeAssessment ea:SummativeAssessment ) .

#################################################################
# AXIS 2: OBJECTIVE / SUBJECTIVE (answer determinacy)
#################################################################

ea:AnswerDeterminacyCategory a owl:Class ;
  owl:disjointUnionOf ( ea:SingleCorrectAnswer ea:MultipleCorrectAnswer ) .

ea:SingleCorrectAnswer a owl:Class .
ea:MultipleCorrectAnswer a owl:Class .

ea:hasAnswerDeterminacy a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:range ea:AnswerDeterminacyCategory ;
  rdfs:comment "Used both on EducationalAssessment and TestItem since the corpus applies the objective/subjective distinction to both assessments and item types." .

ea:ObjectiveAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasAnswerDeterminacy ; owl:someValuesFrom ea:SingleCorrectAnswer ] ) ] ;
  rdfs:comment "A form of questioning that has a single correct answer." .

ea:SubjectiveAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasAnswerDeterminacy ; owl:someValuesFrom ea:MultipleCorrectAnswer ] ) ] ;
  rdfs:comment "A form of questioning that may have more than one correct answer or way of expressing it." .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:ObjectiveAssessment ea:SubjectiveAssessment ) .

#################################################################
# AXIS 3: REFERENCING (Criterion / Norm / Ipsative)
#################################################################

ea:ReferenceCategory a owl:Class ;
  owl:disjointUnionOf ( ea:CriterionReference ea:NormReference ea:IpsativeReference ) .

ea:CriterionReference a owl:Class .
ea:NormReference a owl:Class .
ea:IpsativeReference a owl:Class .

ea:hasReferenceType a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:range ea:ReferenceCategory ;
  rdfs:comment "Applies to both EducationalAssessment (general referencing categorization) and Test (NRT/CRT)." .

ea:CriterionReferencedAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasReferenceType ; owl:someValuesFrom ea:CriterionReference ] ) ] ;
  skos:altLabel "standards-based assessment" ;
  rdfs:comment "Candidates measured against defined, objective criteria, e.g. a driving test." .

ea:NormReferencedAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasReferenceType ; owl:someValuesFrom ea:NormReference ] ) ] ;
  skos:altLabel "normative assessment", "grading on the curve" ;
  rdfs:comment "Relative to the student body taking it, e.g. the IQ test." .

ea:IpsativeAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasReferenceType ; owl:someValuesFrom ea:IpsativeReference ] ) ] ;
  rdfs:comment "Self-comparison either over time or across domains within the same student." .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:CriterionReferencedAssessment ea:NormReferencedAssessment ea:IpsativeAssessment ) .

ea:CriterionReferencedTest a owl:Class ;
  rdfs:subClassOf ea:Test ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasReferenceType ; owl:someValuesFrom ea:CriterionReference ] ) ] ;
  skos:altLabel "CRT" ;
  rdfs:comment "Uses scores to show how well test takers performed on a given task, not how they performed relative to others." .

ea:NormReferencedTest a owl:Class ;
  rdfs:subClassOf ea:Test ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasReferenceType ; owl:someValuesFrom ea:NormReference ] ) ] ;
  skos:altLabel "NRT" ;
  rdfs:comment "Yields an estimate of the position of the tested individual in a predefined population." .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:CriterionReferencedTest ea:NormReferencedTest ) .

ea:MasteryTest a owl:Class ;
  rdfs:subClassOf ea:CriterionReferencedTest ;
  rdfs:comment "A criterion-referenced test involving a cutscore; examinee passes if score exceeds the cutscore." .

ea:hasCutScore a owl:DatatypeProperty ;
  rdfs:domain ea:MasteryTest ;
  rdfs:range xsd:decimal .

ea:NormGroup a owl:Class ;
  skos:altLabel "norming group" ;
  rdfs:comment "Sample drawn from the population used to derive norm-referenced score interpretations." .

ea:hasNormGroup a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:NormReferencedTest ;
  rdfs:range ea:NormGroup .

#################################################################
# SCORE INTERPRETATION (distinct but related classification)
#################################################################

ea:ScoreInterpretation a owl:Class ;
  rdfs:comment "Corpus: 'There are two types of test score interpretations: a norm-referenced score interpretation or a criterion-referenced score interpretation.' Modeled separately from ReferenceCategory because the corpus frames interpretation as a property of how a single test paper is scored ('Each method can be used to grade the same test paper'), not an intrinsic test kind." .

ea:NormReferencedScoreInterpretation a owl:Class ; rdfs:subClassOf ea:ScoreInterpretation .
ea:CriterionReferencedScoreInterpretation a owl:Class ; rdfs:subClassOf ea:ScoreInterpretation .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:NormReferencedScoreInterpretation ea:CriterionReferencedScoreInterpretation ) .

ea:hasScoreInterpretation a owl:ObjectProperty ;
  rdfs:domain ea:Test ;
  rdfs:range ea:ScoreInterpretation .

#################################################################
# AXIS 4: FORMAL / INFORMAL
#################################################################

ea:FormalityCategory a owl:Class ;
  owl:disjointUnionOf ( ea:FormalFormat ea:InformalFormat ) .

ea:FormalFormat a owl:Class .
ea:InformalFormat a owl:Class .

ea:hasFormality a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:FormalityCategory .

ea:FormalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:FormalFormat ] ) ] ;
  rdfs:comment "Usually implies a written document and is given a numerical score or grade contributing to a final grade." .

ea:InformalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:InformalFormat ] ) ] ;
  rdfs:comment "Occurs more casually and does not contribute to a student's final grade." .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:FormalAssessment ea:InformalAssessment ) .

#################################################################
# AXIS 5: INTERNAL / EXTERNAL
#################################################################

ea:AdministrationScopeCategory a owl:Class ;
  owl:disjointUnionOf ( ea:InternalScope ea:ExternalScope ) .

ea:InternalScope a owl:Class .
ea:ExternalScope a owl:Class .

ea:hasAdministrationScope a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:AdministrationScopeCategory .

ea:InternalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasAdministrationScope ; owl:someValuesFrom ea:InternalScope ] ) ] ;
  rdfs:comment "Set and marked by the school/teachers." .

ea:ExternalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:EducationalAssessment
      [ a owl:Restriction ; owl:onProperty ea:hasAdministrationScope ; owl:someValuesFrom ea:ExternalScope ] ) ] ;
  rdfs:comment "Set by the governing body and marked by unbiased personnel." .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:InternalAssessment ea:ExternalAssessment ) .

#################################################################
# AXIS 6: STANDARDIZATION
#################################################################

ea:StandardizationCategory a owl:Class ;
  owl:disjointUnionOf ( ea:StandardizedCondition ea:NonStandardizedCondition ) .

ea:StandardizedCondition a owl:Class .
ea:NonStandardizedCondition a owl:Class .

ea:hasStandardization a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ;
  rdfs:range ea:StandardizationCategory .

ea:StandardizedTest a owl:Class ;
  rdfs:subClassOf ea:Test ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStandardization ; owl:someValuesFrom ea:StandardizedCondition ] ) ] ;
  rdfs:comment "Administered and scored in a consistent or standard manner for all test takers." .

ea:NonStandardizedTest a owl:Class ;
  rdfs:subClassOf ea:Test ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStandardization ; owl:someValuesFrom ea:NonStandardizedCondition ] ) ] ;
  rdfs:comment "Flexible in scope and format, variable in difficulty." .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:StandardizedTest ea:NonStandardizedTest ) .

ea:AchievementTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest ;
  rdfs:comment "Measures knowledge/skills learned in school; 'backward-looking'." .
ea:AptitudeTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest ;
  rdfs:comment "Predicts ability to succeed in a future endeavor; 'forward-looking'." .
ea:CollegeAdmissionsTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
ea:InternationalComparisonTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest ;
  rdfs:comment "E.g. PISA, PIRLS, TIMSS." .
ea:PsychologicalTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest ;
  rdfs:comment "E.g. IQ tests, MMPI." .

#################################################################
# AXIS 7: STAKES
#################################################################

ea:StakesCategory a owl:Class ;
  owl:disjointUnionOf ( ea:HighStakes ea:LowStakes ) .

ea:HighStakes a owl:Class .
ea:LowStakes a owl:Class .

ea:hasStakesLevel a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:StakesCategory .

ea:HighStakesTest a owl:Class ;
  rdfs:subClassOf ea:Test ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStakesLevel ; owl:someValuesFrom ea:HighStakes ] ) ] ;
  rdfs:comment "A test with a desired reward or penalty attached to performance." .

ea:LowStakesTest a owl:Class ;
  rdfs:subClassOf ea:Test ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasStakesLevel ; owl:someValuesFrom ea:LowStakes ] ) ] ;
  rdfs:comment "Ordinary classroom quizzes; low or no point value." .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:HighStakesTest ea:LowStakesTest ) .

ea:Quiz a owl:Class ; rdfs:subClassOf ea:Test, ea:LowStakesTest ;
  rdfs:comment "A brief assessment covering a small amount of material, usually low stakes and formative." .

rdfs:comment "NOTE: the corpus explicitly states that classification axes cross-cut one another: 'Most tests can be classified on multiple categories... a test can be both standardized and also a high-stakes test'. Therefore HighStakesTest/LowStakesTest, StandardizedTest/NonStandardizedTest, CriterionReferencedTest/NormReferencedTest etc. are NOT asserted disjoint from one another across axes -- only within their own axis." .

#################################################################
# AXIS 8: FORMAT (written / oral / practical)
#################################################################

ea:FormatCategory a owl:Class ;
  owl:disjointUnionOf ( ea:WrittenFormat ea:OralFormat ea:PracticalFormat ) .

ea:WrittenFormat a owl:Class .
ea:OralFormat a owl:Class .
ea:PracticalFormat a owl:Class .

ea:hasTestFormat a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Test ;
  rdfs:range ea:FormatCategory .

ea:WrittenTest a owl:Class ;
  rdfs:subClassOf ea:Test ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasTestFormat ; owl:someValuesFrom ea:WrittenFormat ] ) ] .

ea:PerformanceTest a owl:Class ;
  rdfs:subClassOf ea:Test ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
      [ a owl:Restriction ; owl:onProperty ea:hasTestFormat ; owl:someValuesFrom ea:PracticalFormat ] ) ] ;
  skos:altLabel "practical test" ;
  rdfs:comment "Requires an examinee to actually perform a task or activity, e.g. a behind-the-wheel driving test." .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:WrittenTest ea:PerformanceTest ) .

#################################################################
# FURTHER TEST SUBCLASSES
#################################################################

ea:MidtermExam a owl:Class ; rdfs:subClassOf ea:Test ;
  rdfs:comment "Given near the middle of an academic term. Corpus: 'a type of formative or summative assessment' -- stated as an either/or, not forced into both disjoint purpose classes." .

ea:FinalExam a owl:Class ; rdfs:subClassOf ea:Test ;
  rdfs:comment "Final review/assessment at the end of a course; typically summative." .

ea:CompetitiveExamination a owl:Class ;
  rdfs:subClassOf ea:Examination ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Examination
      [ a owl:Restriction ; owl:onProperty ea:hasReferenceType ; owl:someValuesFrom ea:NormReference ]
      [ a owl:Restriction ; owl:onProperty ea:hasStakesLevel ; owl:someValuesFrom ea:HighStakes ] ) ] ;
  rdfs:comment "Norm-referenced, high-stakes tests in which candidates are ranked and top rankers selected." .

ea:InterimAssessment a owl:Class ; rdfs:subClassOf ea:EducationalAssessment ;
  skos:altLabel "benchmark assessment" ;
  rdfs:comment "TENSION: used periodically to track progress toward summative goals. 'Some educators consider interim tests to be formative... but others may consider them to be summative.' No forced subclass relation to Formative or Summative is asserted; the ambiguity is left explicit." .

ea:ScreeningAssessment a owl:Class ; rdfs:subClassOf ea:EducationalAssessment ;
  rdfs:comment "Determines whether students need specialized services or are ready to begin a course/program." .

ea:CommonAssessment a owl:Class ; rdfs:subClassOf ea:EducationalAssessment ;
  rdfs:comment "Used across a school/district for consistent evaluation; may be formative or summative." .

#################################################################
# PERFORMANCE-BASED / AUTHENTIC ASSESSMENT
#################################################################

ea:PerformanceBasedAssessment a owl:Class ;
  rdfs:subClassOf ea:EducationalAssessment ;
  rdfs:comment "Requires students to create, produce, or do something, often with real-world application. Similar to summative assessment in focusing on achievement." .

ea:PerformanceFormatCategory a owl:Class ;
  owl:disjointUnionOf ( ea:ProductFormat ea:LivePerformanceFormat ) .

ea:ProductFormat a owl:Class ; rdfs:comment "E.g. a painting, portfolio, paper, or exhibition." .
ea:LivePerformanceFormat a owl:Class ; rdfs:comment "E.g. a speech, athletic skill, musical recital, reading." .

ea:hasPerformanceFormat a owl:ObjectProperty ;
  rdfs:domain ea:PerformanceBasedAssessment ;
  rdfs:range ea:PerformanceFormatCategory .

ea:AuthenticAssessment a owl:Class ;
  rdfs:subClassOf ea:PerformanceBasedAssessment ;
  rdfs:comment "Measurement of accomplishments within a realistic, practical context relevant outside school. TENSION: one passage lists AuthenticAssessment as a coordinate 'assessment type' alongside PerformanceBasedAssessment, while another ('Performance assessments may also be called authentic assessments') treats the terms as near-synonyms." .

#################################################################
# CONTINUOUS / COMPLEX ASSESSMENT
#################################################################

ea:ContinuousAssessment a owl:Class ;
  rdfs:subClassOf ea:EducationalAssessment ;
  rdfs:comment "Evaluates a student's progress throughout a prescribed course; often includes formative assessment; alternative to a final-exam system." .

ea:ComplexAssessment a owl:Class ;
  rdfs:subClassOf ea:EducationalAssessment ;
  rdfs:comment "Requires a rubric and an expert examiner, e.g. a thesis or funding proposal; complexity arises from ambiguous, implicit assessment criteria." .

#################################################################
# PORTFOLIO
#################################################################

ea:PortfolioBasedAssessment a owl:Class ;
  rdfs:subClassOf ea:EducationalAssessment ;
  rdfs:comment "Uses a compilation of student work (portfolio) to evaluate learning progress and achievement over time." .

ea:Portfolio a owl:Class ;
  rdfs:comment "A compilation of academic work and educational evidence." .

ea:hasArtifact a owl:ObjectProperty ;
  rdfs:domain ea:Portfolio .

ea:PortfolioMediumCategory a owl:Class ;
  owl:disjointUnionOf ( ea:DigitalPortfolioMedium ea:PhysicalPortfolioMedium ) .

ea:DigitalPortfolioMedium a owl:Class .
ea:PhysicalPortfolioMedium a owl:Class .

ea:hasPortfolioMedium a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Portfolio ;
  rdfs:range ea:PortfolioMediumCategory .

ea:DigitalPortfolio a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Portfolio
      [ a owl:Restriction ; owl:onProperty ea:hasPortfolioMedium ; owl:someValuesFrom ea:DigitalPortfolioMedium ] ) ] ;
  skos:altLabel "e-portfolio" .

ea:PhysicalPortfolio a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Portfolio
      [ a owl:Restriction ; owl:onProperty ea:hasPortfolioMedium ; owl:someValuesFrom ea:PhysicalPortfolioMedium ] ) ] .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:DigitalPortfolio ea:PhysicalPortfolio ) .

ea:CapstonePortfolio a owl:Class ; rdfs:subClassOf ea:Portfolio ;
  rdfs:comment "Features student work completed as part of long-term/culminating projects." .

#################################################################
# TEST ITEM TAXONOMY
#################################################################

ea:TestItem a owl:Class ;
  rdfs:comment "A unit of a test, more general than 'question' since many items are not phrased as questions." .

ea:hasItem a owl:ObjectProperty ;
  rdfs:domain ea:Test ;
  rdfs:range ea:TestItem .

ea:isItemOf a owl:ObjectProperty ;
  owl:inverseOf ea:hasItem ;
  rdfs:domain ea:TestItem ;
  rdfs:range ea:Test .

ea:Stem a owl:Class ;
  rdfs:comment "The opening of an item: a problem, question, or incomplete statement." .

ea:hasStem a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:TestItem ;
  rdfs:range ea:Stem .

ea:AnswerOption a owl:Class ;
  rdfs:comment "A possible answer offered to the examinee." .

ea:hasOption a owl:ObjectProperty ;
  rdfs:domain ea:TestItem ;
  rdfs:range ea:AnswerOption .

ea:hasCorrectOption a owl:ObjectProperty ;
  rdfs:subPropertyOf ea:hasOption ;
  rdfs:domain ea:TestItem ;
  rdfs:range ea:AnswerOption .

ea:Key a owl:Class ; rdfs:subClassOf ea:AnswerOption ;
  rdfs:comment "The correct answer option." .
ea:Distractor a owl:Class ; rdfs:subClassOf ea:AnswerOption ;
  rdfs:comment "An incorrect answer option." .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:Key ea:Distractor ) .

ea:ObjectiveItem a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:TestItem
      [ a owl:Restriction ; owl:onProperty ea:hasAnswerDeterminacy ; owl:someValuesFrom ea:SingleCorrectAnswer ] ) ] ;
  rdfs:comment "Objective question types include true/false, multiple-choice, multiple-response, and matching." .

ea:SubjectiveItem a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:TestItem
      [ a owl:Restriction ; owl:onProperty ea:hasAnswerDeterminacy ; owl:someValuesFrom ea:MultipleCorrectAnswer ] ) ] ;
  rdfs:comment "Subjective items include extended-response and essay questions." .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:ObjectiveItem ea:SubjectiveItem ) .

ea:MultipleChoiceItem a owl:Class ;
  rdfs:subClassOf ea:ObjectiveItem ;
  owl:equivalentClass [ owl:intersectionOf ( ea:ObjectiveItem
      [ a owl:Restriction ; owl:onProperty ea:hasCorrectOption ; owl:qualifiedCardinality "1"^^xsd:nonNegativeInteger ; owl:onClass ea:AnswerOption ] ) ] ;
  skos:altLabel "MCQ", "objective response" ;
  rdfs:comment "Only one answer may be keyed as correct; stem plus alternative answers. The corpus also describes two families of multiple-choice question: the True/False family (choose all that are appropriate) and the One-Best-Answer family (choose exactly one) -- creating tension with TrueFalseItem being modeled elsewhere as a coordinate sibling type rather than a subtype of MultipleChoiceItem." .

ea:MultipleResponseItem a owl:Class ;
  rdfs:subClassOf ea:ObjectiveItem ;
  owl:equivalentClass [ owl:intersectionOf ( ea:ObjectiveItem
      [ a owl:Restriction ; owl:onProperty ea:hasCorrectOption ; owl:minQualifiedCardinality "2"^^xsd:nonNegativeInteger ; owl:onClass ea:AnswerOption ] ) ] ;
  rdfs:comment "More than one answer may be keyed as correct, contrasted explicitly with MultipleChoiceItem." .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:MultipleChoiceItem ea:MultipleResponseItem ) .

ea:TrueFalseItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem .
ea:MatchingItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem .

ea:FillInTheBlankItem a owl:Class ; rdfs:subClassOf ea:TestItem ;
  rdfs:comment "Requires recall of a correct term; difficulty varies by presence/absence of a word bank." .

ea:FreeResponseItem a owl:Class ;
  rdfs:subClassOf ea:SubjectiveItem ;
  skos:altLabel "FRQ", "extended-response item" ;
  rdfs:comment "Requires a prose response; graded for factual correctness, persuasiveness, style, mastery." .

ea:EssayItem a owl:Class ; rdfs:subClassOf ea:FreeResponseItem .
ea:ShortAnswerItem a owl:Class ; rdfs:subClassOf ea:FreeResponseItem .

#################################################################
# GRADING APPROACH (Holistic / Analytic) AND RUBRICS
#################################################################

ea:GradingApproach a owl:Class ;
  rdfs:comment "An approach to scoring student work." .

ea:HolisticGrading a owl:Class ;
  rdfs:subClassOf ea:GradingApproach ;
  owl:disjointWith ea:AnalyticGrading ;
  skos:altLabel "holistic scoring", "nonreductionist grading" ;
  rdfs:comment "Bases a grade on a paper's overall quality, treating the composition as a whole." .

ea:AnalyticGrading a owl:Class ;
  rdfs:subClassOf ea:GradingApproach ;
  rdfs:comment "Involves criterion-by-criterion judgments, taking more factors into account." .

ea:TraitInformedScoring a owl:Class ;
  rdfs:subClassOf ea:HolisticGrading ;
  rdfs:comment "Trains raters to score against a rubric of multiple traits, but asks raters to take all traits into account before deciding on a single final score -- 'remains holistic at heart' despite coming close to analytic scoring methods. This hybrid status is the source of a modeling tension between HolisticGrading and AnalyticGrading." .

ea:Rubric a owl:Class ;
  rdfs:comment "A scoring guide used to evaluate the quality of students' constructed responses; a set of criteria, quality definitions, and a scoring strategy." .

ea:RubricTypeCategory a owl:Class ;
  owl:disjointUnionOf ( ea:HolisticRubricType ea:AnalyticRubricType ea:DevelopmentalRubricType ) .

ea:HolisticRubricType a owl:Class .
ea:AnalyticRubricType a owl:Class .
ea:DevelopmentalRubricType a owl:Class .

ea:hasRubricType a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Rubric ;
  rdfs:range ea:RubricTypeCategory .

ea:HolisticRubric a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Rubric
      [ a owl:Restriction ; owl:onProperty ea:hasRubricType ; owl:someValuesFrom ea:HolisticRubricType ] ) ] ;
  rdfs:comment "Provides an overall rating for a piece of work." .

ea:AnalyticRubric a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Rubric
      [ a owl:Restriction ; owl:onProperty ea:hasRubricType ; owl:someValuesFrom ea:AnalyticRubricType ] ) ] ;
  rdfs:comment "Evaluates various dimensions or components separately." .

ea:DevelopmentalRubric a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Rubric
      [ a owl:Restriction ; owl:onProperty ea:hasRubricType ; owl:someValuesFrom ea:DevelopmentalRubricType ] ) ] ;
  rdfs:subClassOf ea:AnalyticRubric ;
  rdfs:comment "TENSION: 'Rubrics can be classified as holistic, analytic, or developmental' presents Developmental as a coordinate third kind, but the same passage then states 'Developmental rubrics, a subset of analytical rubrics' -- both the coordinate partition and the subsumption are encoded." .

#################################################################
# QUALITY ATTRIBUTES: RELIABILITY AND VALIDITY
#################################################################

ea:QualityAttribute a owl:Class ;
  rdfs:comment "A good assessment has both validity and reliability." .

ea:Reliability a owl:Class ; rdfs:subClassOf ea:QualityAttribute ;
  rdfs:comment "The consistency of an assessment; freedom of a measure from measurement error." .

ea:Validity a owl:Class ; rdfs:subClassOf ea:QualityAttribute ;
  rdfs:comment "The degree to which an assessment measures what it is supposed to measure." .

ea:hasReliability a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:Reliability .

ea:hasValidity a owl:ObjectProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:Validity .

ea:hasReliabilityCoefficient a owl:DatatypeProperty ;
  rdfs:domain ea:Reliability ;
  rdfs:range xsd:decimal ;
  rdfs:comment "Ranges from 0.00 (much error) to 1.00 (no error)." .

#--- Reliability error-source classification ("four types of reliability") ---
ea:ReliabilitySourceCategory a owl:Class ;
  owl:disjointUnionOf ( ea:StudentRelatedSource ea:RaterRelatedSource
                         ea:TestAdministrationRelatedSource ea:TestRelatedSource ) ;
  rdfs:comment "'There are four types of reliability: student-related... rater-related... test administration-related... and test-related.'" .

ea:StudentRelatedSource a owl:Class .
ea:RaterRelatedSource a owl:Class .
ea:TestAdministrationRelatedSource a owl:Class .
ea:TestRelatedSource a owl:Class .

ea:hasReliabilitySource a owl:ObjectProperty ;
  rdfs:domain ea:Reliability ;
  rdfs:range ea:ReliabilitySourceCategory .

#--- Reliability estimation methods ("several general classes of reliability estimates") ---
ea:ReliabilityEstimationMethod a owl:Class ;
  rdfs:comment "TENSION: this is a second, independent classification of reliability (by estimation technique) distinct from the four error-source 'types' above; the corpus uses the word 'types'/'classes' for both schemes without reconciling them." .

ea:InterRaterReliability a owl:Class ; rdfs:subClassOf ea:ReliabilityEstimationMethod ;
  rdfs:comment "Degree of agreement between two or more raters." .

ea:TestRetestReliability a owl:Class ; rdfs:subClassOf ea:ReliabilityEstimationMethod ;
  skos:altLabel "repeatability", "temporal stability" ;
  rdfs:comment "Consistency of scores from one test administration to the next." .

ea:InterMethodReliability a owl:Class ; rdfs:subClassOf ea:ReliabilityEstimationMethod ;
  skos:altLabel "parallel-forms reliability", "form equivalence" ;
  rdfs:comment "Consistency when there is variation in the methods/instruments used." .

ea:InternalConsistencyReliability a owl:Class ; rdfs:subClassOf ea:ReliabilityEstimationMethod ;
  rdfs:comment "Consistency of results across items within a test; most common measure is Cronbach's alpha." .

ea:SplitHalfReliability a owl:Class ;
  rdfs:subClassOf ea:InterMethodReliability ;
  rdfs:comment "Treats the two halves of a measure as alternate forms; also closely related to InternalConsistencyReliability (Cronbach's alpha is the mean of all possible split-half coefficients)." .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:InterRaterReliability ea:TestRetestReliability
                ea:InterMethodReliability ea:InternalConsistencyReliability ) .

#--- Validity evidence categories ---
ea:ContentValidity a owl:Class ; rdfs:subClassOf ea:Validity ;
  skos:altLabel "logical validity" ;
  rdfs:comment "Does the content of the test measure stated objectives / cover a representative sample of the behavior domain?" .

ea:CriterionValidity a owl:Class ; rdfs:subClassOf ea:Validity ;
  skos:altLabel "criterion-related validity" ;
  rdfs:comment "Correlation between the test and a criterion variable taken as representative of the construct." .

ea:ConstructValidity a owl:Class ; rdfs:subClassOf ea:Validity ;
  rdfs:comment "Extent to which operationalizations of a construct measure the construct as defined by theory." .

ea:ConsequentialValidity a owl:Class ; rdfs:subClassOf ea:Validity .
ea:FaceValidity a owl:Class ; rdfs:subClassOf ea:Validity ;
  rdfs:comment "Estimate of whether a test appears, on its face, to measure a certain criterion." .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:ContentValidity ea:CriterionValidity ea:ConstructValidity
                ea:ConsequentialValidity ea:FaceValidity ) .

ea:ContentValidity rdfs:subClassOf ea:ConstructValidity .
ea:CriterionValidity rdfs:subClassOf ea:ConstructValidity .
ea:FaceValidity rdfs:subClassOf ea:ConstructValidity .

[] a owl:Axiom ;
   rdfs:comment "TENSION: validity evidence categories (Content, Criterion, Construct, Consequential, Face) are presented as a coordinate enumerated list ('Validity... is generally gauged through examination of evidence in the following categories...'), and are therefore asserted pairwise disjoint above; however the corpus also states 'Construct validity... subsumes all other types of validity', which is encoded here as ContentValidity, CriterionValidity and FaceValidity being rdfs:subClassOf ConstructValidity -- directly conflicting with the disjointness axiom." .

ea:CriterionMeasurementTimingCategory a owl:Class ;
  owl:disjointUnionOf ( ea:SameTimeTiming ea:LaterTimeTiming ) .

ea:SameTimeTiming a owl:Class .
ea:LaterTimeTiming a owl:Class .

ea:hasCriterionMeasurementTiming a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:CriterionValidity ;
  rdfs:range ea:CriterionMeasurementTimingCategory .

ea:ConcurrentValidity a owl:Class ;
  rdfs:subClassOf ea:CriterionValidity ;
  owl:equivalentClass [ owl:intersectionOf ( ea:CriterionValidity
      [ a owl:Restriction ; owl:onProperty ea:hasCriterionMeasurementTiming ; owl:someValuesFrom ea:SameTimeTiming ] ) ] ;
  rdfs:comment "Test data and criterion data collected at the same time." .

ea:PredictiveValidity a owl:Class ;
  rdfs:subClassOf ea:CriterionValidity ;
  owl:equivalentClass [ owl:intersectionOf ( ea:CriterionValidity
      [ a owl:Restriction ; owl:onProperty ea:hasCriterionMeasurementTiming ; owl:someValuesFrom ea:LaterTimeTiming ] ) ] ;
  rdfs:comment "Test data collected first, to predict criterion data collected later." .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:ConcurrentValidity ea:PredictiveValidity ) .

ea:ConvergentValidity a owl:Class ; rdfs:subClassOf ea:ConstructValidity ;
  rdfs:comment "Measure is associated with things it should be associated with." .
ea:DiscriminantValidity a owl:Class ; rdfs:subClassOf ea:ConstructValidity ;
  rdfs:comment "Measure is not associated with things it should not be associated with." .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:ConvergentValidity ea:DiscriminantValidity ) .

#################################################################
# LEARNING OUTCOME
#################################################################

ea:LearningOutcome a owl:Class ;
  rdfs:comment "A statement about what students should be able to do by the end of a teaching session." .

ea:hasLearningOutcome a owl:ObjectProperty ;
  rdfs:domain ea:EducationalAssessment ;
  rdfs:range ea:LearningOutcome .

ea:IntendedLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome ;
  skos:altLabel "aim" .
ea:MeasuredLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome ;
  skos:altLabel "objective" .
ea:UnintendedLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome ;
  rdfs:comment "Beneficial outcomes neither planned nor sought but simply observed." .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:IntendedLearningOutcome ea:MeasuredLearningOutcome ea:UnintendedLearningOutcome ) .

#################################################################
# FEEDBACK
#################################################################

ea:Feedback a owl:Class ;
  rdfs:comment "Information given to a learner about their understanding or performance." .

ea:CorrectiveFeedback a owl:Class ;
  rdfs:subClassOf ea:Feedback ;
  rdfs:comment "Nonevaluative, supportive, timely, specific feedback on understanding or performance." .

ea:Recast a owl:Class ;
  rdfs:subClassOf ea:CorrectiveFeedback ;
  rdfs:comment "A subtle correction of a young child's spoken errors by a parent/caregiver." .

#################################################################
# LEARNING TYPES (formal / non-formal / informal learning)
#################################################################

ea:Learning a owl:Class ;
  rdfs:comment "Acquisition of knowledge/skill, classified by structure/organization." .

ea:FormalLearning a owl:Class ; rdfs:subClassOf ea:Learning .
ea:NonFormalLearning a owl:Class ; rdfs:subClassOf ea:Learning ;
  rdfs:comment "Organized learning outside the formal learning system, e.g. clubs, workshops." .
ea:InformalLearning a owl:Class ; rdfs:subClassOf ea:Learning ;
  rdfs:comment "Less structured than non-formal learning; occurs through day-to-day experience." .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:FormalLearning ea:NonFormalLearning ea:InformalLearning ) .

#################################################################
# TRANSFER OF LEARNING
#################################################################

ea:TransferOfLearning a owl:Class ;
  rdfs:comment "Application of skill, knowledge, or understanding to resolve a novel problem/situation." .

ea:NearTransfer a owl:Class ; rdfs:subClassOf ea:TransferOfLearning ;
  rdfs:comment "Application of skill to a novel problem in a similar context." .
ea:FarTransfer a owl:Class ; rdfs:subClassOf ea:TransferOfLearning ;
  rdfs:comment "Application of skill to a novel problem in a different context." .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:NearTransfer ea:FarTransfer ) .

ea:PositiveTransfer a owl:Class ; rdfs:subClassOf ea:TransferOfLearning ;
  rdfs:comment "Prior learning supports novel problem solving." .
ea:NegativeTransfer a owl:Class ; rdfs:subClassOf ea:TransferOfLearning ;
  rdfs:comment "Prior learning inhibits performance on highly correlated tasks." .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:PositiveTransfer ea:NegativeTransfer ) .

#################################################################
# PERIPHERAL CONCEPTS (lightly modeled for coverage)
#################################################################

ea:ValueAddedMeasure a owl:Class ;
  skos:altLabel "growth measure" ;
  rdfs:comment "Statistical estimate of a teacher's effect on student learning using standardized-test results and student growth percentiles." .

ea:Proficiency a owl:Class ;
  rdfs:comment "A level/scale/cut-off-score determination of whether a student has achieved expected learning standards." .

ea:MeasurementError a owl:Class ;
  rdfs:comment "Difference between what a test score indicates and a student's actual knowledge/ability (X = T + E)." .

ea:ScoreInflation a owl:Class ;
  rdfs:comment "Increase in scores that does not reflect genuine improvement in learning." .

ea:CompetencyBasedLearning a owl:Class ;
  skos:altLabel "proficiency-based learning", "mastery-based learning", "outcome-based learning", "performance-based learning", "standards-based learning" ;
  rdfs:comment "Instruction/assessment/grading/reporting based on demonstrated learning rather than seat time." .

ea:ConstructiveAlignment a owl:Class ;
  rdfs:comment "Principle for devising teaching, learning, and assessment tasks that directly address intended learning outcomes." .

#################################################################
# GENERIC DATATYPE PROPERTIES
#################################################################

ea:hasItemCount a owl:DatatypeProperty ;
  rdfs:domain ea:Test ;
  rdfs:range xsd:integer .

ea:hasDifficultyLevel a owl:DatatypeProperty ;
  rdfs:domain ea:TestItem ;
  rdfs:range xsd:string .

ea:hasObservedScore a owl:DatatypeProperty ; rdfs:domain ea:EducationalAssessment ; rdfs:range xsd:decimal .
ea:hasTrueScore a owl:DatatypeProperty ; rdfs:domain ea:EducationalAssessment ; rdfs:range xsd:decimal .
ea:hasMeasurementErrorValue a owl:DatatypeProperty ; rdfs:domain ea:EducationalAssessment ; rdfs:range xsd:decimal .
