```turtle
@prefix ea:   <http://example.org/onto/assessment#> .
@prefix owl:  <http://www.w3.org/2002/07/owl#> .
@prefix rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs: <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:  <http://www.w3.org/2001/XMLSchema#> .
@prefix skos: <http://www.w3.org/2004/02/skos/core#> .

<http://example.org/onto/assessment> a owl:Ontology ;
  rdfs:comment """Ontology of educational assessment built from a corpus that classifies
  assessment along several independent, mostly-orthogonal axes (purpose, response format,
  referencing, formality, administering authority, standardization, stakes) and that also
  contains internally conflicting classification claims (e.g. diagnostic assessment as a
  coordinate sibling of formative assessment vs. diagnostic as a subtype of formative;
  construct validity as a coordinate category vs. construct validity subsuming all other
  validity types; performance-based assessment vs. authentic assessment as disjoint
  coordinate kinds vs. the claim that they 'may also be called' the same thing; rubrics
  classified as a 3-way coordinate partition vs. developmental rubric being a subset of
  analytic rubric; value-added measure and growth measure treated as synonyms vs. as
  distinct). Per modeling instructions, both sides of each conflict are asserted and
  flagged with rdfs:comment rather than silently resolved; this intentionally renders
  some classes jointly unsatisfiable, mirroring the source disagreement. The corpus also
  explicitly states that a single test can have multiple simultaneous qualities across
  different axes ('Most tests can be classified on multiple categories'), so classes
  belonging to DIFFERENT axes are never asserted disjoint; only classes enumerated as
  alternatives WITHIN the same axis are made disjoint.""" .

###############################################################################
# TOP CLASS
###############################################################################

ea:Assessment a owl:Class ;
  rdfs:label "Assessment" ;
  skos:altLabel "educational evaluation" ;
  rdfs:comment "The systematic process of documenting and using empirical data on knowledge, skill, attitudes, aptitude and beliefs to refine programs and improve student learning. Often used interchangeably with 'test' but not limited to tests." .

ea:Test a owl:Class ;
  rdfs:subClassOf ea:Assessment ;
  rdfs:label "Test" ;
  skos:altLabel "Examination", "Exam", "Evaluation" ;
  rdfs:comment "An examination (exam or evaluation), or test, is an educational assessment intended to measure knowledge, skill, aptitude etc. NOTE: the corpus's top-level passage also uses 'evaluation' as a synonym of the broad Assessment class, creating a terminological tension with 'evaluation' also being used here as a synonym of the narrower Test class." .

###############################################################################
# GRANULARITY AXIS
###############################################################################

ea:hasGranularity a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:GranularityLevel .

ea:GranularityLevel a owl:Class .
ea:LearnerGranularity a owl:Class .
ea:LearningCommunityGranularity a owl:Class .
ea:CourseGranularity a owl:Class .
ea:ProgramGranularity a owl:Class .
ea:InstitutionGranularity a owl:Class .
ea:EducationalSystemGranularity a owl:Class .
ea:GranularityLevel owl:disjointUnionOf
  ( ea:LearnerGranularity ea:LearningCommunityGranularity ea:CourseGranularity
    ea:ProgramGranularity ea:InstitutionGranularity ea:EducationalSystemGranularity ) .

###############################################################################
# AXIS 1: PURPOSE (placement, formative, summative, diagnostic)
###############################################################################

ea:hasPurpose a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:PurposeCategory .

ea:PurposeCategory a owl:Class .
ea:PlacementPurpose a owl:Class .
ea:FormativePurpose a owl:Class .
ea:SummativePurpose a owl:Class .
ea:DiagnosticPurpose a owl:Class .
ea:PurposeCategory owl:disjointUnionOf
  ( ea:PlacementPurpose ea:FormativePurpose ea:SummativePurpose ea:DiagnosticPurpose ) .

ea:PlacementAssessment a owl:Class ;
  rdfs:label "Placement assessment" ;
  skos:altLabel "pre-assessment", "initial assessment", "threshold knowledge test" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:PlacementPurpose ] ) ] .

ea:FormativeAssessment a owl:Class ;
  rdfs:label "Formative assessment" ;
  skos:altLabel "educative assessment", "assessment for learning", "classroom assessment", "formative evaluation" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:FormativePurpose ] ) ] .

ea:SummativeAssessment a owl:Class ;
  rdfs:label "Summative assessment" ;
  skos:altLabel "assessment of learning", "summative evaluation" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:SummativePurpose ] ) ] .

ea:DiagnosticAssessment a owl:Class ;
  rdfs:label "Diagnostic assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasPurpose ; owl:someValuesFrom ea:DiagnosticPurpose ] ) ] ;
  rdfs:subClassOf ea:FormativeAssessment ;
  rdfs:comment "TENSION: one passage lists placement/formative/summative/diagnostic as four coordinate, mutually exclusive categories (modeled by the disjoint PurposeCategory union above); another passage states 'A common form of formative assessment is diagnostic assessment', subordinating Diagnostic under Formative (modeled by the subClassOf above). Because hasPurpose is functional and FormativePurpose/DiagnosticPurpose are disjoint, this class is intentionally unsatisfiable, reflecting the corpus conflict." .

ea:ContinuousAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Evaluates progress throughout a course; often includes some form of formative assessment." .

# Assessor sub-axis for formative assessment agent
ea:hasAssessor a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:Assessor .
ea:Assessor a owl:Class .
ea:TeacherAssessor a owl:Class .
ea:PeerAssessor a owl:Class .
ea:LearnerAssessor a owl:Class ; rdfs:label "Learner (self) assessor" .
ea:Assessor owl:disjointUnionOf ( ea:TeacherAssessor ea:PeerAssessor ea:LearnerAssessor ) .

ea:SelfAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:DiagnosticAssessment
    [ a owl:Restriction ; owl:onProperty ea:hasAssessor ; owl:someValuesFrom ea:LearnerAssessor ] ) ] ;
  rdfs:comment "Self-assessment is a form of diagnostic assessment in which students assess themselves." .

# Temporal orientation (forward/backward looking)
ea:hasTemporalOrientation a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:TemporalOrientationCategory .
ea:TemporalOrientationCategory a owl:Class .
ea:PastOrientation a owl:Class .
ea:FutureOrientation a owl:Class .
ea:TemporalOrientationCategory owl:disjointUnionOf ( ea:PastOrientation ea:FutureOrientation ) .

ea:ForwardLookingAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasTemporalOrientation ; owl:someValuesFrom ea:FutureOrientation ] ) ] ;
  rdfs:comment "Asks those being assessed to consider themselves in hypothetical future situations." .

###############################################################################
# PERFORMANCE-BASED / AUTHENTIC ASSESSMENT (with recorded conflict)
###############################################################################

ea:PerformanceBasedAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
  rdfs:label "Performance-based assessment" ;
  rdfs:comment "Similar to summative assessment in focusing on achievement; a well-defined task is identified and students create/produce/do something, often with real-world application." .

ea:AuthenticAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Measurement of accomplishments within a realistic, practical context relevant outside the school setting." .

ea:PerformanceAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
  rdfs:label "Performance assessment" ;
  rdfs:comment "Glossary sense: requires completion of a complex task; 'may also be called authentic assessments'." .

# Coordinate-list claim: Performance-based assessment and Authentic assessment are
# listed side by side as distinct "Assessment types" -> disjoint.
ea:PerformanceBasedAssessment owl:disjointWith ea:AuthenticAssessment .
# Later glossary claim: performance assessment "may also be called" authentic assessment -> equated.
ea:PerformanceAssessment owl:equivalentClass ea:AuthenticAssessment ;
  rdfs:comment "TENSION: 'Assessment types' enumerates Performance-based assessment and Authentic assessment as disjoint coordinate kinds, while the glossary states performance assessments 'may also be called authentic assessments' (equated here). Both claims are encoded, which jointly renders ea:PerformanceAssessment/ea:AuthenticAssessment/ea:PerformanceBasedAssessment unsatisfiable if ea:PerformanceAssessment is also identified with ea:PerformanceBasedAssessment (same underlying notion of 'performance assessment')." .
ea:PerformanceAssessment owl:equivalentClass ea:PerformanceBasedAssessment .

# Performance output sub-classification
ea:hasOutputFormat a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:PerformanceBasedAssessment ; rdfs:range ea:OutputCategory .
ea:OutputCategory a owl:Class .
ea:ProductOutput a owl:Class .
ea:PerformanceOutput a owl:Class .
ea:OutputCategory owl:disjointUnionOf ( ea:ProductOutput ea:PerformanceOutput ) .

###############################################################################
# AXIS 2: OBJECTIVE / SUBJECTIVE
###############################################################################

ea:hasResponseType a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:ResponseCategory .
ea:ResponseCategory a owl:Class .
ea:ObjectiveCategory a owl:Class .
ea:SubjectiveCategory a owl:Class .
ea:ResponseCategory owl:disjointUnionOf ( ea:ObjectiveCategory ea:SubjectiveCategory ) .

ea:ObjectiveAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasResponseType ; owl:someValuesFrom ea:ObjectiveCategory ] ) ] ;
  rdfs:comment "A form of questioning that has a single correct answer." .

ea:SubjectiveAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasResponseType ; owl:someValuesFrom ea:SubjectiveCategory ] ) ] ;
  rdfs:comment "A form of questioning that may have more than one correct answer." .

###############################################################################
# AXIS 3: REFERENCING (criterion / norm / ipsative)
###############################################################################

ea:hasReferencing a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:ReferencingCategory .
ea:ReferencingCategory a owl:Class .
ea:CriterionReferencing a owl:Class .
ea:NormReferencing a owl:Class .
ea:IpsativeReferencing a owl:Class .
ea:ReferencingCategory owl:disjointUnionOf
  ( ea:CriterionReferencing ea:NormReferencing ea:IpsativeReferencing ) .

ea:CriterionReferencedAssessment a owl:Class ;
  skos:altLabel "standards-based assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:CriterionReferencing ] ) ] .

ea:CriterionReferencedTest a owl:Class ;
  skos:altLabel "CRT" ;
  rdfs:subClassOf ea:Test, ea:CriterionReferencedAssessment ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:CriterionReferencing ] ) ] ;
  rdfs:comment "Candidates are measured against defined, objective criteria regardless of other examinees' scores; it is possible for all, or none, to pass." .

ea:NormReferencedAssessment a owl:Class ;
  skos:altLabel "normative assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:NormReferencing ] ) ] .

ea:NormReferencedTest a owl:Class ;
  skos:altLabel "NRT" ;
  rdfs:subClassOf ea:Test, ea:NormReferencedAssessment ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:NormReferencing ] ) ] ;
  rdfs:comment "Yields an estimate of the position of the tested individual in a predefined population." .

ea:IpsativeAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:IpsativeReferencing ] ) ] ;
  rdfs:comment "Self-comparison either in the same domain over time, or comparative to other domains within the same student." .

ea:hasCutScore a owl:DatatypeProperty, owl:FunctionalProperty ;
  rdfs:domain ea:CriterionReferencedTest ; rdfs:range xsd:decimal .

ea:MasteryTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:CriterionReferencedTest
    [ a owl:Restriction ; owl:onProperty ea:hasCutScore ; owl:someValuesFrom xsd:decimal ] ) ] ;
  rdfs:comment "A criterion-referenced test involving a cutscore where the examinee passes if the score exceeds the cutscore." .

###############################################################################
# AXIS 4: FORMAL / INFORMAL
###############################################################################

ea:hasFormality a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:FormalityCategory .
ea:FormalityCategory a owl:Class .
ea:FormalCategory a owl:Class .
ea:InformalCategory a owl:Class .
ea:FormalityCategory owl:disjointUnionOf ( ea:FormalCategory ea:InformalCategory ) .

ea:FormalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:FormalCategory ] ) ] ;
  rdfs:comment "Usually implies a written document and a numerical score or grade based on student performance." .

ea:InformalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasFormality ; owl:someValuesFrom ea:InformalCategory ] ) ] ;
  rdfs:comment "Does not contribute to a student's final grade; e.g. observation, checklists, rubrics used informally." .

###############################################################################
# AXIS 5: INTERNAL / EXTERNAL
###############################################################################

ea:hasAdministeringAuthority a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:AdministeringAuthorityCategory .
ea:AdministeringAuthorityCategory a owl:Class .
ea:InternalAuthorityCategory a owl:Class .
ea:ExternalAuthorityCategory a owl:Class .
ea:AdministeringAuthorityCategory owl:disjointUnionOf
  ( ea:InternalAuthorityCategory ea:ExternalAuthorityCategory ) .

ea:InternalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasAdministeringAuthority ; owl:someValuesFrom ea:InternalAuthorityCategory ] ) ] ;
  rdfs:comment "Set and marked by the school/teachers." .

ea:ExternalAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasAdministeringAuthority ; owl:someValuesFrom ea:ExternalAuthorityCategory ] ) ] ;
  rdfs:comment "Set by the governing body and marked by unbiased personnel." .

###############################################################################
# AXIS 6: STANDARDIZATION (applies to Assessment generally; primarily discussed for Test)
###############################################################################

ea:hasStandardizationStatus a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:StandardizationCategory .
ea:StandardizationCategory a owl:Class .
ea:StandardizedCategory a owl:Class .
ea:NonStandardizedCategory a owl:Class .
ea:StandardizationCategory owl:disjointUnionOf ( ea:StandardizedCategory ea:NonStandardizedCategory ) .

ea:StandardizedTest a owl:Class ;
  skos:altLabel "standardized assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasStandardizationStatus ; owl:someValuesFrom ea:StandardizedCategory ] ) ] ;
  rdfs:comment "Administered and scored in a consistent or standard manner for all test takers." .

ea:NonStandardizedTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasStandardizationStatus ; owl:someValuesFrom ea:NonStandardizedCategory ] ) ] ;
  rdfs:comment "Flexible in scope and format, variable in difficulty." .

# Representative kinds of standardized test (coordinate, enumerated -> disjoint)
ea:AchievementTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest, ea:ForwardLookingAssessment ;
  owl:equivalentClass [ owl:intersectionOf ( ea:StandardizedTest
    [ a owl:Restriction ; owl:onProperty ea:hasTemporalOrientation ; owl:someValuesFrom ea:PastOrientation ] ) ] ;
  rdfs:comment "Backward-looking: measures knowledge/skills already learned." .
ea:AptitudeTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:StandardizedTest
    [ a owl:Restriction ; owl:onProperty ea:hasTemporalOrientation ; owl:someValuesFrom ea:FutureOrientation ] ) ] ;
  rdfs:comment "Forward-looking: attempts to predict future ability to succeed." .
ea:CollegeAdmissionsTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
ea:InternationalComparisonTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
ea:PsychologicalTest a owl:Class ; rdfs:subClassOf ea:StandardizedTest .
[] a owl:AllDisjointClasses ;
  owl:members ( ea:AchievementTest ea:AptitudeTest ea:CollegeAdmissionsTest
                ea:InternationalComparisonTest ea:PsychologicalTest ) .

###############################################################################
# AXIS 7: STAKES
###############################################################################

ea:hasStakesLevel a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Assessment ; rdfs:range ea:StakesCategory .
ea:StakesCategory a owl:Class .
ea:HighStakesCategory a owl:Class .
ea:LowStakesCategory a owl:Class .
ea:StakesCategory owl:disjointUnionOf ( ea:HighStakesCategory ea:LowStakesCategory ) .

ea:HighStakesTest a owl:Class ;
  skos:altLabel "high-stakes assessment" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasStakesLevel ; owl:someValuesFrom ea:HighStakesCategory ] ) ] ;
  rdfs:comment "A test with a desired reward or important consequence for performance; defined by its function (how results are used), not its form." .

ea:LowStakesTest a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasStakesLevel ; owl:someValuesFrom ea:LowStakesCategory ] ) ] .

ea:CompetitiveExamination a owl:Class ; rdfs:subClassOf ea:Test ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Test
    [ a owl:Restriction ; owl:onProperty ea:hasReferencing ; owl:someValuesFrom ea:NormReferencing ]
    [ a owl:Restriction ; owl:onProperty ea:hasStakesLevel ; owl:someValuesFrom ea:HighStakesCategory ] ) ] ;
  rdfs:comment "Norm-referenced, high-stakes tests in which candidates are ranked and the top n are selected." .

###############################################################################
# OTHER NAMED ASSESSMENT KINDS FROM ENUMERATED LISTS (overlap explicitly allowed)
###############################################################################

ea:InterimAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Used to monitor progress toward summative benchmarks; some educators consider it formative, others summative - corpus leaves this an open disagreement rather than resolving it." .
ea:ScreeningAssessment a owl:Class ; rdfs:subClassOf ea:Assessment .
ea:CommonAssessment a owl:Class ; rdfs:subClassOf ea:Assessment ;
  rdfs:comment "Shares format and administration across teachers/classrooms for consistency; may be formative or summative." .
ea:PortfolioBasedAssessment a owl:Class ; rdfs:subClassOf ea:Assessment .

###############################################################################
# EXAMINATION / TEST ARTIFACTS: ITEMS
###############################################################################

ea:TestItem a owl:Class ; rdfs:label "Test item" .
ea:hasItem a owl:ObjectProperty ; rdfs:domain ea:Test ; rdfs:range ea:TestItem .
ea:isItemOf a owl:ObjectProperty ; owl:inverseOf ea:hasItem ; rdfs:domain ea:TestItem ; rdfs:range ea:Test .

ea:hasItemResponseType a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:TestItem ; rdfs:range ea:ResponseCategory .

ea:ObjectiveItem a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:TestItem
    [ a owl:Restriction ; owl:onProperty ea:hasItemResponseType ; owl:someValuesFrom ea:ObjectiveCategory ] ) ] .
ea:SubjectiveItem a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:TestItem
    [ a owl:Restriction ; owl:onProperty ea:hasItemResponseType ; owl:someValuesFrom ea:SubjectiveCategory ] ) ] .

ea:hasStem a owl:DatatypeProperty, owl:FunctionalProperty ; rdfs:domain ea:TestItem ; rdfs:range xsd:string .
ea:TestItemOption a owl:Class .
ea:hasOption a owl:ObjectProperty ; rdfs:domain ea:TestItem ; rdfs:range ea:TestItemOption .
ea:hasKey a owl:ObjectProperty ; rdfs:subPropertyOf ea:hasOption ; rdfs:domain ea:TestItem ; rdfs:range ea:TestItemOption ;
  rdfs:comment "The option(s) marked correct." .
ea:hasDistractor a owl:ObjectProperty ; rdfs:subPropertyOf ea:hasOption ; rdfs:domain ea:TestItem ; rdfs:range ea:TestItemOption ;
  rdfs:comment "An incorrect option." .

ea:MultipleChoiceItem a owl:Class ;
  skos:altLabel "MCQ", "multiple choice question", "objective response" ;
  owl:equivalentClass [ owl:intersectionOf ( ea:ObjectiveItem
    [ a owl:Restriction ; owl:onProperty ea:hasKey ; owl:onClass ea:TestItemOption ;
      owl:qualifiedCardinality "1"^^xsd:nonNegativeInteger ] ) ] .

ea:MultipleResponseItem a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:ObjectiveItem
    [ a owl:Restriction ; owl:onProperty ea:hasKey ; owl:onClass ea:TestItemOption ;
      owl:minQualifiedCardinality "2"^^xsd:nonNegativeInteger ] ) ] ;
  rdfs:comment "More than one answer may be keyed as correct, contrasting with MultipleChoiceItem." .

ea:TrueFalseItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem ;
  rdfs:comment "TENSION: listed here as a coordinate objective item type alongside MultipleChoiceItem/MultipleResponseItem/MatchingItem. Elsewhere the corpus describes 'two families' of multiple-choice question where the 'True/False family' requires choosing ALL appropriate answers (conceptually equivalent to MultipleResponseItem) and the 'One-Best-Answer family' requires a single answer (conceptually equivalent to MultipleChoiceItem) - i.e. True/False is there treated as a family of multiple choice rather than a sibling item type." .

ea:MatchingItem a owl:Class ; rdfs:subClassOf ea:ObjectiveItem .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:TrueFalseItem ea:MultipleChoiceItem ea:MultipleResponseItem ea:MatchingItem ) .

ea:ExtendedResponseItem a owl:Class ; rdfs:subClassOf ea:SubjectiveItem .
ea:EssayItem a owl:Class ; rdfs:subClassOf ea:SubjectiveItem ;
  skos:altLabel "essay question", "free response question", "FRQ" ;
  rdfs:comment "An open-ended question requiring a prose response, graded for factual correctness, persuasiveness, style and mastery." .
ea:ShortAnswerItem a owl:Class ; rdfs:subClassOf ea:SubjectiveItem .
[] a owl:AllDisjointClasses ;
  owl:members ( ea:ExtendedResponseItem ea:EssayItem ea:ShortAnswerItem ) .

ea:FillInTheBlankItem a owl:Class ; rdfs:subClassOf ea:TestItem .
ea:MathItem a owl:Class ; rdfs:subClassOf ea:TestItem ;
  rdfs:comment "Mathematics/calculation question scored more for steps than final answer." .

###############################################################################
# PERFORMANCE TEST
###############################################################################

ea:PerformanceTest a owl:Class ; rdfs:subClassOf ea:Assessment ;
  skos:altLabel "work sample" ;
  rdfs:comment "Requires an examinee to actually perform a task or activity rather than answer questions about it." .
ea:Simulation a owl:Class ; rdfs:subClassOf ea:PerformanceTest .

###############################################################################
# COMPLEX ASSESSMENT (genus + differentia definition)
###############################################################################

ea:Rubric a owl:Class .
ea:Examiner a owl:Class .
ea:ExpertExaminer a owl:Class ; rdfs:subClassOf ea:Examiner .
ea:hasRubric a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:Rubric .
ea:hasExaminer a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:Examiner .

ea:ComplexAssessment a owl:Class ;
  owl:equivalentClass [ owl:intersectionOf ( ea:Assessment
    [ a owl:Restriction ; owl:onProperty ea:hasRubric ; owl:someValuesFrom ea:Rubric ]
    [ a owl:Restriction ; owl:onProperty ea:hasExaminer ; owl:someValuesFrom ea:ExpertExaminer ] ) ] ;
  rdfs:comment "An assessment that requires a rubric and an expert examiner, e.g. a thesis or funding proposal." .

###############################################################################
# RUBRIC TYPES (coordinate 3-way list vs. subset claim)
###############################################################################

ea:HolisticRubric a owl:Class ; rdfs:subClassOf ea:Rubric .
ea:AnalyticRubric a owl:Class ; rdfs:subClassOf ea:Rubric .
ea:DevelopmentalRubric a owl:Class ; rdfs:subClassOf ea:Rubric .
ea:Rubric owl:disjointUnionOf ( ea:HolisticRubric ea:AnalyticRubric ea:DevelopmentalRubric ) .
ea:DevelopmentalRubric rdfs:subClassOf ea:AnalyticRubric ;
  rdfs:comment "TENSION: 'Rubrics can be classified as holistic, analytic, or developmental' presents three coordinate (and, per modeling convention, disjoint) kinds, while the same passage also states 'Developmental rubrics, a subset of analytical rubrics' - subordinating Developmental under Analytic. Both are asserted, which is logically unsatisfiable for ea:DevelopmentalRubric; this mirrors the source conflict." .

###############################################################################
# GRADING TYPES
###############################################################################

ea:Grading a owl:Class .
ea:HolisticGrading a owl:Class ; rdfs:subClassOf ea:Grading ;
  skos:altLabel "holistic scoring", "nonreductionist grading" ;
  rdfs:comment "Bases a grade on a paper's overall quality, treating the composition as a whole." .
ea:AnalyticGrading a owl:Class ; rdfs:subClassOf ea:Grading ;
  rdfs:comment "Takes more factors into account separately when assigning a grade; contrasts with holistic grading." .
ea:HolisticGrading owl:disjointWith ea:AnalyticGrading .
ea:TraitInformedScoring a owl:Class ; rdfs:subClassOf ea:HolisticGrading ;
  rdfs:comment "Trains raters to a scoring guide covering several criteria; comes close to analytic scoring methods, yet 'remains holistic at heart' since a single final score is produced." .

###############################################################################
# VALIDITY (coordinate categories vs. subsumption claim)
###############################################################################

ea:Validity a owl:Class ;
  rdfs:comment "The degree to which an assessment measures what it is supposed to measure." .
ea:hasValidityCoefficient a owl:DatatypeProperty ; rdfs:domain ea:Validity ; rdfs:range xsd:decimal .

ea:ContentValidity a owl:Class ; skos:altLabel "logical validity" .
ea:CriterionValidity a owl:Class ; skos:altLabel "criterion-related validity" .
ea:ConstructValidity a owl:Class .
ea:ConsequentialValidity a owl:Class .
ea:FaceValidity a owl:Class .

ea:ValidityCategory a owl:Class .
ea:ValidityCategory owl:disjointUnionOf
  ( ea:ContentValidity ea:CriterionValidity ea:ConstructValidity ea:ConsequentialValidity ea:FaceValidity ) ;
  rdfs:comment "Models the passage stating evidence is gauged through content validity, criterion validity, construct validity, plus consequential and face validity, treated as coordinate categories of evidence." .

ea:ContentValidity rdfs:subClassOf ea:ConstructValidity .
ea:CriterionValidity rdfs:subClassOf ea:ConstructValidity .
ea:ConstructValidity rdfs:comment "TENSION: one passage enumerates content/criterion/construct validity (plus consequential and face validity) as coordinate, disjoint categories of validity evidence (see ea:ValidityCategory). A later passage states construct validity 'subsumes all other types of validity', and that 'construct validity is not distinct from support for the substantive theory'. Both claims are modeled: the disjoint union above, and the subClassOf assertions making ContentValidity and CriterionValidity subtypes of ConstructValidity, which is logically inconsistent with the disjoint union - intentionally, per corpus conflict." ;
  rdfs:subClassOf ea:Validity .

ea:hasMeasurementTiming a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:CriterionValidity ; rdfs:range ea:TimingCategory .
ea:TimingCategory a owl:Class .
ea:SameTimeTiming a owl:Class .
ea:LaterTimeTiming a owl:Class .
ea:TimingCategory owl:disjointUnionOf ( ea:SameTimeTiming ea:LaterTimeTiming ) .

ea:ConcurrentValidity a owl:Class ; rdfs:subClassOf ea:Validity ;
  owl:equivalentClass [ owl:intersectionOf ( ea:CriterionValidity
    [ a owl:Restriction ; owl:onProperty ea:hasMeasurementTiming ; owl:someValuesFrom ea:SameTimeTiming ] ) ] ;
  rdfs:comment "Test data and criterion data collected at the same time." .
ea:PredictiveValidity a owl:Class ; rdfs:subClassOf ea:Validity ;
  owl:equivalentClass [ owl:intersectionOf ( ea:CriterionValidity
    [ a owl:Restriction ; owl:onProperty ea:hasMeasurementTiming ; owl:someValuesFrom ea:LaterTimeTiming ] ) ] ;
  rdfs:comment "Test data collected first to predict criterion data collected at a later time." .

ea:ConvergentValidity a owl:Class ; rdfs:subClassOf ea:ConstructValidity .
ea:DiscriminantValidity a owl:Class ; rdfs:subClassOf ea:ConstructValidity .
ea:ConstructValidity owl:disjointUnionOf ( ea:ConvergentValidity ea:DiscriminantValidity ) ;
  rdfs:comment "Convergent and discriminant validity are the two subtypes of validity that make up construct validity." .

ea:hasValidity a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:Validity .

###############################################################################
# RELIABILITY (two independent "types of reliability" classifications)
###############################################################################

ea:Reliability a owl:Class ;
  rdfs:comment "The consistency of an assessment; a reliable assessment consistently achieves the same results with the same/similar cohort." .
ea:hasReliability a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:Reliability .
ea:hasReliabilityCoefficient a owl:DatatypeProperty ; rdfs:domain ea:Reliability ; rdfs:range xsd:decimal .

# Classification 1: "several general classes of reliability estimates"
ea:InterRaterReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  rdfs:comment "Degree of agreement between two or more raters." .
ea:TestRetestReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  skos:altLabel "repeatability" ;
  rdfs:comment "Degree to which test scores are consistent from one administration to the next by a single rater." .
ea:InterMethodReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  rdfs:comment "Degree to which scores are consistent when the methods/instruments vary; termed parallel-forms reliability when dealing with forms." .
ea:ParallelFormsReliability a owl:Class ; rdfs:subClassOf ea:InterMethodReliability .
ea:InternalConsistencyReliability a owl:Class ; rdfs:subClassOf ea:Reliability ;
  rdfs:comment "Consistency of results across items within a test (e.g. Cronbach's alpha)." .
ea:SplitHalfReliability a owl:Class ; rdfs:subClassOf ea:InternalConsistencyReliability ;
  rdfs:comment "Treats two halves of a measure as alternate forms, stepped up via Spearman-Brown formula." .

[] a owl:AllDisjointClasses ;
  owl:members ( ea:InterRaterReliability ea:TestRetestReliability
                ea:InterMethodReliability ea:InternalConsistencyReliability ) .

# Classification 2: "There are four types of reliability" (error-source axis)
ea:hasErrorSource a owl:ObjectProperty, owl:FunctionalProperty ;
  rdfs:domain ea:Reliability ; rdfs:range ea:ErrorSourceCategory .
ea:ErrorSourceCategory a owl:Class .
ea:StudentRelatedErrorSource a owl:Class .
ea:RaterRelatedErrorSource a owl:Class .
ea:TestAdministrationRelatedErrorSource a owl:Class .
ea:TestRelatedErrorSource a owl:Class .
ea:ErrorSourceCategory owl:disjointUnionOf
  ( ea:StudentRelatedErrorSource ea:RaterRelatedErrorSource
    ea:TestAdministrationRelatedErrorSource ea:TestRelatedErrorSource ) ;
  rdfs:comment "TENSION: the corpus separately states 'There are four types of reliability: student-related, rater-related, test administration-related, and test-related' (an error-source classification) AND 'There are several general classes of reliability estimates: inter-rater, test-retest, inter-method, internal consistency' (a method classification). Both are modeled as independent axes of ea:Reliability, since the corpus itself calls both of them 'types of reliability' without reconciling them." .

###############################################################################
# SCORE INTERPRETATION
###############################################################################

ea:ScoreInterpretation a owl:Class .
ea:NormReferencedScoreInterpretation a owl:Class ; rdfs:subClassOf ea:ScoreInterpretation .
ea:CriterionReferencedScoreInterpretation a owl:Class ; rdfs:subClassOf ea:ScoreInterpretation .
ea:ScoreInterpretation owl:disjointUnionOf
  ( ea:NormReferencedScoreInterpretation ea:CriterionReferencedScoreInterpretation ) .

###############################################################################
# LEARNING OUTCOMES
###############################################################################

ea:LearningOutcome a owl:Class .
ea:IntendedLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome ; skos:altLabel "aim" .
ea:MeasuredLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome ; skos:altLabel "objective" .
ea:UnintendedLearningOutcome a owl:Class ; rdfs:subClassOf ea:LearningOutcome .
ea:LearningOutcome owl:disjointUnionOf
  ( ea:IntendedLearningOutcome ea:MeasuredLearningOutcome ea:UnintendedLearningOutcome ) .
ea:hasLearningOutcome a owl:ObjectProperty ; rdfs:domain ea:Assessment ; rdfs:range ea:LearningOutcome .

###############################################################################
# PORTFOLIOS
###############################################################################

ea:Portfolio a owl:Class ; rdfs:subClassOf ea:PortfolioBasedAssessment .
ea:DigitalPortfolio a owl:Class ; rdfs:subClassOf ea:Portfolio ; skos:altLabel "e-portfolio" .
ea:CapstonePortfolio a owl:Class ; rdfs:subClassOf ea:Portfolio .

###############################################################################
# TESTS BY TIMING IN A COURSE
###############################################################################

ea:Quiz a owl:Class ; rdfs:subClassOf ea:Test, ea:FormativeAssessment ;
  rdfs:comment "A brief assessment covering a small amount of material; usually low stakes and formative." .
ea:Midterm a owl:Class ; rdfs:subClassOf ea:Test ;
  rdfs:comment "An exam given near the middle of an academic term; the corpus states it 'is a type of formative or summative assessment' (either, not necessarily both)." .
ea:FinalExamination a owl:Class ; rdfs:subClassOf ea:Test, ea:SummativeAssessment ;
  rdfs:comment "A greater form of a 'unit test' given at the conclusion of a course." .

###############################################################################
# MEASUREMENT ERROR (two senses given by the corpus)
###############################################################################

ea:MeasurementError a owl:Class .
ea:TestMeasurementError a owl:Class ; rdfs:subClassOf ea:MeasurementError ;
  rdfs:comment "Difference between what a test score indicates and a student's actual knowledge/abilities." .
ea:DataReportingMeasurementError a owl:Class ; rdfs:subClassOf ea:MeasurementError ;
  rdfs:comment "Errors introduced when collecting and calculating data-based reports, figures and statistics about schools and students." .
ea:MeasurementError owl:disjointUnionOf ( ea:TestMeasurementError ea:DataReportingMeasurementError ) .

###############################################################################
# TEACHER-EVALUATION MEASURES (synonym vs. distinct tension)
###############################################################################

ea:TeacherEvaluationMeasure a owl:Class .
ea:ValueAddedMeasure a owl:Class ; rdfs:subClassOf ea:TeacherEvaluationMeasure ;
  skos:altLabel "growth measure" ;
  rdfs:comment "Initially introduced as synonymous with 'growth measure' ('Value-added measures, or growth measures'), but see ea:StudentGrowthMeasure for the corpus's later claim that these are distinct." .
ea:StudentGrowthMeasure a owl:Class ; rdfs:subClassOf ea:TeacherEvaluationMeasure ;
  owl:disjointWith ea:ValueAddedMeasure ;
  rdfs:comment "TENSION: the corpus later states 'Student growth measures are a related-but-distinct method' from value-added measures, contradicting the earlier treatment of 'value-added measures' and 'growth measures' as the same term (see altLabel on ea:ValueAddedMeasure)." .

###############################################################################
# COMPETENCY-BASED LEARNING (system-level classification, loosely tied to assessment)
###############################################################################

ea:CompetencyBasedLearning a owl:Class ;
  skos:altLabel "proficiency-based learning", "mastery-based learning", "outcome-based learning",
                "performance-based learning", "standards-based learning" ;
  rdfs:comment "Systems of instruction, assessment, grading and academic reporting based on students demonstrating learned knowledge/skills; many synonymous terms are used interchangeably by the corpus." .

