    rdfs:subClassOf ea:MeasurementError .

ea:DevelopmentalRubric a owl:Class ;
    rdfs:comment "NOTE: 'Rubrics can be classified as holistic, analytic, or developmental' presents three coordinate (disjoint) kinds. The source also states 'Developmental rubrics, a subset of analytical rubrics'; that subsumption claim has been dropped to keep the coordinate partition consistent." ;
    rdfs:subClassOf ea:Rubric .

ea:DiagnosticAssessment a owl:Class ;
    rdfs:label "Diagnostic assessment" ;
    rdfs:comment "NOTE: one passage lists placement/formative/summative/diagnostic as four coordinate, mutually exclusive categories (modeled by the disjoint PurposeCategory union above); another passage states 'A common form of formative assessment is diagnostic assessment', subordinating Diagnostic under Formative. The subsumption under FormativeAssessment has been removed to keep the coordinate partition consistent, since hasPurpose is functional and FormativePurpose/DiagnosticPurpose are disjoint." ;
    owl:equivalentClass [ owl:intersectionOf ( ea:Assessment [ a owl:Restriction ;
                        owl:onProperty ea:hasPurpose ;
                        owl:someValuesFrom ea:DiagnosticPurpose ] ) ] .

ea:DiscriminantValidity a owl:Class ;
